// ─── Shared components ──────────────────────────────────────────────────────
function NavBar({ onHome, onAbout }: any) {
  return (
    <nav style={{
      position: "sticky", top: 0, zIndex: 100,
      background: "rgba(27,67,50,0.97)", backdropFilter: "blur(10px)",
      padding: "0 24px"
    }}>
      <div style={{
        maxWidth: 1100, margin: "0 auto",
        display: "flex", alignItems: "center", justifyContent: "space-between",
        height: 58
      }}>
        <button onClick={onHome} style={{
          display: "flex", alignItems: "center", gap: 10,
          background: "transparent", border: "none", cursor: "pointer"
        }}>
          <span style={{ fontSize: 26 }}>🐾</span>
          <div style={{ textAlign: "left" }}>
            <div style={{ fontFamily: "'Noto Serif Thai', serif", fontWeight: 700, fontSize: 18, color: "#fff", lineHeight: 1.2 }}>หมอยาเหมียวๆ</div>
            <div style={{ fontSize: 10, color: "#86efac", letterSpacing: "0.06em" }}>สารานุกรมสมุนไพรไทย</div>
          </div>
        </button>
        <button onClick={onAbout}
          style={{
            display: "flex", alignItems: "center", gap: 8,
            padding: "8px 18px", borderRadius: 10,
            border: "1px solid rgba(255,255,255,0.3)",
            background: "rgba(255,255,255,0.1)", color: "#d1fae5",
            fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit",
            backdropFilter: "blur(4px)"
          }}>
          📖 ประวัติเว็บไซต์
        </button>
      </div>
    </nav>
  );
}

// ─── HOME PAGE ──────────────────────────────────────────────────────────────
function HomePage({ onSelectHerb }: any) {
  const [search, setSearch] = useState("");
  const filtered = HERBS.filter(h =>
    h.name.includes(search) || h.latin.toLowerCase().includes(search.toLowerCase()) || h.shortDesc.includes(search)
  );

  return (
    <div style={{ background: "#f8f5ef", minHeight: "100vh" }}>
      {/* Hero Banner */}
      <div style={{ position: "relative", height: 240, overflow: "hidden" }}>
        <img src={BANNER} alt="" style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "center top" }} />
        <div style={{ position: "absolute", inset: 0, background: "linear-gradient(to bottom, rgba(27,67,50,0.75) 0%, rgba(27,67,50,0.5) 60%, rgba(248,245,239,0.9) 100%)" }} />
        <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: "0 20px" }}>
          <h1 style={{
            fontFamily: "'Noto Serif Thai', serif",
            fontSize: 38, fontWeight: 700, color: "#fff",
            textShadow: "0 2px 12px rgba(0,0,0,0.4)",
            margin: "0 0 8px", textAlign: "center"
          }}>🌿 สมุนไพรไทย</h1>
          <p style={{ color: "#d1fae5", fontSize: 16, margin: "0 0 20px", textAlign: "center" }}>
            เลือกสมุนไพรที่อยากรู้จัก อ่านง่าย เข้าใจเร็ว ถาม AI ได้ทันที
          </p>
          {/* Search bar */}
          <div style={{
            display: "flex", alignItems: "center", gap: 10,
            background: "#fff", borderRadius: 16, padding: "10px 20px",
            boxShadow: "0 4px 24px rgba(0,0,0,0.15)", width: "100%", maxWidth: 480
          }}>
            <span style={{ fontSize: 20, opacity: 0.5 }}>🔍</span>
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="ค้นหาสมุนไพร หรือพิมพ์อาการ เช่น หวัด เจ็บคอ..."
              style={{
                flex: 1, border: "none", outline: "none",
                fontSize: 15, background: "transparent",
                fontFamily: "'Noto Sans Thai', sans-serif"
              }}
            />
          </div>
        </div>
      </div>

      {/* Herb Grid */}
      <div style={{ maxWidth: 1100, margin: "0 auto", padding: "32px 20px 60px" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24 }}>
          <div>
            <h2 style={{ fontFamily: "'Noto Serif Thai', serif", fontSize: 22, fontWeight: 700, color: "#1B4332", margin: "0 0 4px" }}>
              สมุนไพรทั้งหมด
            </h2>
            <div style={{ fontSize: 13, color: "#6b7280" }}>{filtered.length} ชนิด</div>
          </div>
        </div>

        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(4, 1fr)",
          gap: 20
        }}>
          {filtered.map(herb => (
            <HerbCard key={herb.id} herb={herb} onClick={() => onSelectHerb(herb)} />
          ))}
        </div>

        {filtered.length === 0 && (
          <div style={{ textAlign: "center", padding: "60px 20px", color: "#9ca3af" }}>
            <div style={{ fontSize: 48, marginBottom: 12 }}>🌿</div>
            <div style={{ fontSize: 16 }}>ไม่พบสมุนไพรที่ค้นหา ลองคำใหม่นะคะ</div>
          </div>
        )}
      </div>
    </div>
  );
}

// ─── HERB CARD ──────────────────────────────────────────────────────────────
function HerbCard({ herb, onClick }: any) {
  const [hovered, setHovered] = useState(false);
  return (
    <div
      onClick={onClick}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        background: "#fff",
        borderRadius: 20,
        overflow: "hidden",
        boxShadow: hovered ? "0 8px 32px rgba(27,67,50,0.15)" : "0 2px 16px rgba(27,67,50,0.07)",
        border: hovered ? "2px solid #86efac" : "2px solid transparent",
        cursor: "pointer",
        transition: "all 0.2s ease",
        transform: hovered ? "translateY(-4px)" : "none",
        display: "flex",
        flexDirection: "column"
      }}>

      {/* Image area */}
      <div style={{ position: "relative", height: 180, overflow: "hidden", background: "#e8f5e9", flexShrink: 0 }}>
        {herb.cardImg ? (
          <img
            src={herb.cardImg}
            alt={herb.name}
            style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "center",
              transition: "transform 0.3s ease",
              transform: hovered ? "scale(1.05)" : "scale(1)" }}
          />
        ) : (
          <div style={{ width: "100%", height: "100%", display: "flex", alignItems: "center", justifyContent: "center",
            fontSize: 64,
            background: "linear-gradient(135deg, #f0fdf4, #dcfce7)" }}>
            {herb.emoji}
          </div>
        )}
        {/* Tag badge */}
        {herb.tag && (
          <div style={{
            position: "absolute", top: 12, left: 12,
            background: herb.tagColor, color: "#fff",
            fontSize: 11, fontWeight: 700,
            padding: "4px 10px", borderRadius: 999,
            boxShadow: "0 2px 8px rgba(0,0,0,0.2)"
          }}>{herb.tag}</div>
        )}
        {/* Overlay gradient on hover */}
        <div style={{
          position: "absolute", inset: 0,
          background: "linear-gradient(to top, rgba(27,67,50,0.4) 0%, transparent 50%)",
          opacity: hovered ? 1 : 0, transition: "opacity 0.2s"
        }} />
      </div>

      {/* Content */}
      <div style={{ padding: "16px 18px 18px", display: "flex", flexDirection: "column", flex: 1, gap: 6 }}>
        <div style={{ fontFamily: "'Noto Serif Thai', serif", fontWeight: 700, fontSize: 18, color: "#1B4332", lineHeight: 1.3 }}>
          {herb.name}
        </div>
        <div style={{ fontSize: 12, color: "#9ca3af", fontStyle: "italic", marginBottom: 4 }}>
          {herb.latin}
        </div>
        <p style={{
          fontSize: 13, color: "#6b7280", lineHeight: 1.6, flex: 1,
          display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical", overflow: "hidden"
        }}>
          {herb.shortDesc}
        </p>
        <button style={{
          marginTop: 10, padding: "9px 0",
          background: hovered ? "#1B4332" : "#f0fdf4",
          color: hovered ? "#fff" : "#1B4332",
          border: "1.5px solid #bbf7d0",
          borderRadius: 10, fontSize: 13, fontWeight: 700,
          cursor: "pointer", fontFamily: "inherit",
          transition: "all 0.2s"
        }}>
          อ่านเพิ่มเติม →
        </button>
      </div>
    </div>
  );
}

// ─── DETAIL PAGE ─────────────────────────────────────────────────────────────
function DetailPage({ herb, onBack }: any) {
  const [messages, setMessages] = useState([{
    role: "assistant",
    text: `สวัสดีค่ะ 😺 มีคำถามเรื่อง${herb.name}ไหมคะ?`
  }]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);

  const send = async (text) => {
    const q = text || input.trim();
    if (!q || loading) return;
    setInput("");
    setMessages(prev => [...prev, { role: "user", text: q }]);
    setLoading(true);
    try {
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6", max_tokens: 400,
          system: `คุณคือ AI ผู้ช่วยของเว็บ "หมอยาเหมียวๆ" เว็บสารานุกรมสมุนไพรไทย ตอบภาษาไทย เป็นกันเอง เหมือนครูสอนวิทยาศาสตร์ ไม่ใช้ศัพท์แพทย์ซับซ้อน เตือนให้ปรึกษาแพทย์เมื่อจำเป็น`,
          messages: [...messages.map(m => ({ role: m.role, content: m.text })), { role: "user", content: q }]
        })
      });
      const data = await res.json();
      const reply = data.content?.find(c => c.type === "text")?.text || "ขออภัยค่ะ ลองใหม่นะคะ";
      setMessages(prev => [...prev, { role: "assistant", text: reply }]);
    } catch {
      setMessages(prev => [...prev, { role: "assistant", text: "เชื่อมต่อไม่ได้ค่ะ 🙏" }]);
    }
    setLoading(false);
  };

  const sugQ = herb.suggestedQ || ["กินกับพาราได้ไหม?","เด็กกินได้ไหม?","คนท้องกินได้ไหม?","กินนานแค่ไหน?"];

  return (
    <div style={{ background: "#f8f5ef", minHeight: "100vh" }}>

      {/* Hero image with herb name overlay */}
      <div style={{ position: "relative", height: 380, overflow: "hidden" }}>
        {herb.heroImg ? (
          <img src={herb.heroImg} alt={herb.name} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "center" }} />
        ) : (
          <div style={{ width: "100%", height: "100%", background: "linear-gradient(135deg, #166534, #1B4332)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 80 }}>
            {herb.emoji}
          </div>
        )}
        <div style={{ position: "absolute", inset: 0, background: "linear-gradient(to top, rgba(0,0,0,0.75) 0%, rgba(0,0,0,0.1) 60%, transparent 100%)" }} />

        {/* Back button */}
        <button onClick={onBack} style={{
          position: "absolute", top: 20, left: 24,
          background: "rgba(0,0,0,0.4)", backdropFilter: "blur(8px)",
          border: "1px solid rgba(255,255,255,0.3)",
          color: "#fff", padding: "8px 16px", borderRadius: 10,
          cursor: "pointer", fontSize: 14, fontFamily: "inherit",
          display: "flex", alignItems: "center", gap: 6
        }}>← กลับ</button>

        {/* Name overlay */}
        <div style={{ position: "absolute", bottom: 0, left: 0, right: 0, padding: "24px 32px" }}>
          {herb.tag && (
            <div style={{
              display: "inline-block", background: herb.tagColor,
              color: "#fff", fontSize: 11, fontWeight: 700,
              padding: "4px 12px", borderRadius: 999, marginBottom: 10
            }}>{herb.tag}</div>
          )}
          <h1 style={{
            fontFamily: "'Noto Serif Thai', serif",
            fontSize: 42, fontWeight: 700, color: "#fff",
            textShadow: "0 2px 12px rgba(0,0,0,0.5)", margin: "0 0 6px"
          }}>{herb.name}</h1>
          <div style={{ color: "rgba(255,255,255,0.75)", fontSize: 16, fontStyle: "italic" }}>{herb.latin}</div>
        </div>
      </div>

      {/* Content */}
      <div style={{ maxWidth: 1000, margin: "0 auto", padding: "32px 20px 60px" }}>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 24 }}>

          {/* COL LEFT */}
          <div style={{ display: "flex", flexDirection: "column", gap: 24 }}>

            {/* สมุนไพรนี้คืออะไร */}
            <div style={{ background: "#fff", borderRadius: 24, padding: 28, boxShadow: "0 2px 20px rgba(27,67,50,0.07)", border: "1px solid #e8f5e9" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
                <span style={{ fontSize: 26 }}>🌿</span>
                <h2 style={{ fontFamily: "'Noto Serif Thai',serif", fontSize: 20, fontWeight: 700, color: "#1B4332", margin: 0 }}>สมุนไพรนี้คืออะไร</h2>
              </div>
              <p style={{ fontSize: 15, lineHeight: 1.8, color: "#374151", marginBottom: 14 }}>{herb.intro}</p>
              {(herb.family || herb.partUsed) && (
                <div style={{ display: "flex", gap: 10, marginBottom: 16 }}>
                  {herb.family && (
                    <div style={{ flex: 1, padding: "10px 14px", background: "#f0fdf4", borderRadius: 12, border: "1px solid #bbf7d0" }}>
                      <div style={{ fontSize: 11, color: "#16a34a", fontWeight: 700, marginBottom: 3 }}>🌿 วงศ์พืช</div>
                      <div style={{ fontSize: 13, color: "#374151", fontWeight: 600 }}>{herb.family}</div>
                    </div>
                  )}
                  {herb.partUsed && (
                    <div style={{ flex: 1, padding: "10px 14px", background: "#eff6ff", borderRadius: 12, border: "1px solid #bfdbfe" }}>
                      <div style={{ fontSize: 11, color: "#1565C0", fontWeight: 700, marginBottom: 3 }}>💊 ส่วนที่ใช้เป็นยา</div>
                      <div style={{ fontSize: 13, color: "#374151", fontWeight: 600 }}>{herb.partUsed}</div>
                    </div>
                  )}
                </div>
              )}
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 16 }}>
                {(herb.plantInfo||[]).map((p, i) => (
                  <div key={i} style={{ padding: "12px 14px", background: "#f0fdf4", borderRadius: 14, border: "1px solid #bbf7d0" }}>
                    <div style={{ fontSize: 20, marginBottom: 4 }}>{p.icon}</div>
                    <div style={{ fontSize: 11, color: "#16a34a", fontWeight: 700, marginBottom: 2 }}>{p.label}</div>
                    <div style={{ fontSize: 13, color: "#374151" }}>{p.value}</div>
                  </div>
                ))}
              </div>
              <div style={{ background: "#f8f5ef", borderRadius: 14, padding: 16, marginBottom: 12 }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: "#1B4332", marginBottom: 10 }}>🗺️ ชื่อเรียกในแต่ละภาค</div>
                <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                  {(herb.regionalNames||[]).map((r, i) => (
                    <div key={i} style={{ display: "flex", justifyContent: "space-between" }}>
                      <span style={{ fontSize: 12, color: "#6b7280" }}>{r.region}</span>
                      <span style={{ fontSize: 13, fontWeight: 600, color: "#1B4332" }}>{r.name}</span>
                    </div>
                  ))}
                </div>
              </div>
              <div style={{ padding: "12px 14px", background: "#eff6ff", borderRadius: 12, border: "1px solid #bfdbfe" }}>
                <div style={{ fontSize: 12, fontWeight: 600, color: "#1565C0", marginBottom: 3 }}>📍 พบได้ที่ไหน</div>
                <p style={{ fontSize: 13, color: "#374151", margin: 0, lineHeight: 1.6 }}>{herb.whereToFind}</p>
              </div>
            </div>

            {/* คนสมัยก่อนใช้ทำอะไร */}
            <div style={{ background: "#fff", borderRadius: 24, padding: 28, boxShadow: "0 2px 20px rgba(27,67,50,0.07)", border: "1px solid #e8f5e9" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
                <span style={{ fontSize: 26 }}>📖</span>
                <h2 style={{ fontFamily: "'Noto Serif Thai',serif", fontSize: 20, fontWeight: 700, color: "#1B4332", margin: 0 }}>คนสมัยก่อนใช้ทำอะไร</h2>
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {(herb.ancientUses||[]).map((u, i) => (
                  <div key={i} style={{ display: "flex", alignItems: "center", gap: 14, padding: "13px 16px", background: "#f8f5ef", borderRadius: 14 }}>
                    <span style={{ fontSize: 26, flexShrink: 0 }}>{u.icon}</span>
                    <span style={{ fontSize: 14, color: "#374151", lineHeight: 1.5 }}>{u.text}</span>
                  </div>
                ))}
              </div>
              <div style={{ marginTop: 14, padding: "10px 14px", background: "#fef9c3", borderRadius: 10, border: "1px solid #fde047" }}>
                <p style={{ fontSize: 12, color: "#92400e", margin: 0, fontStyle: "italic" }}>💬 เป็นภูมิปัญญาพื้นบ้าน ไม่ควรใช้แทนคำแนะนำทางการแพทย์</p>
              </div>
            </div>



            {/* สารสำคัญ */}
            <div style={{ background: "#fff", borderRadius: 24, padding: 28, boxShadow: "0 2px 20px rgba(27,67,50,0.07)", border: "1px solid #e8f5e9" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
                <span style={{ fontSize: 26 }}>🧪</span>
                <h2 style={{ fontFamily: "'Noto Serif Thai',serif", fontSize: 20, fontWeight: 700, color: "#1B4332", margin: 0 }}>สารสำคัญในตัว</h2>
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {(herb.compounds||[]).map((cmp, i) => (
                  <div key={i} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "13px 16px", background: "#f0fdf4", borderRadius: 13, border: "1px solid #bbf7d0" }}>
                    <span style={{ fontWeight: 700, fontSize: 14, color: "#1B4332", fontFamily: "monospace" }}>{cmp.name}</span>
                    <span style={{ fontSize: 13, color: "#6b7280", textAlign: "right", maxWidth: "55%" }}>{cmp.desc}</span>
                  </div>
                ))}
              </div>
            </div>          </div>

          {/* COL RIGHT */}
          <div style={{ display: "flex", flexDirection: "column", gap: 24 }}>

            {/* ใช้เมื่อมีอาการ + วิธีใช้ */}
            <div style={{ background: "#fff", borderRadius: 24, padding: 28, boxShadow: "0 2px 20px rgba(27,67,50,0.07)", border: "1px solid #e8f5e9" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
                <span style={{ fontSize: 26 }}>✅</span>
                <h2 style={{ fontFamily: "'Noto Serif Thai',serif", fontSize: 20, fontWeight: 700, color: "#1B4332", margin: 0 }}>ใช้เมื่อมีอาการแบบไหน</h2>
              </div>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 24 }}>
                {(herb.goodFor||[]).map((g, i) => (
                  <div key={i} style={{ padding: "18px 14px", background: "#f0fdf4", borderRadius: 18, border: "2px solid #bbf7d0", textAlign: "center" }}>
                    <div style={{ fontSize: 32, marginBottom: 8 }}>{g.icon}</div>
                    <div style={{ fontSize: 13, fontWeight: 700, color: "#1B4332" }}>{g.label}</div>
                  </div>
                ))}
              </div>
              <div style={{ borderTop: "1px solid #e8f5e9", paddingTop: 20 }}>
                <div style={{ fontSize: 15, fontWeight: 700, color: "#1B4332", marginBottom: 12 }}>🫖 วิธีใช้แบบพื้นบ้าน</div>
                <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                  {(herb.howToUse||[]).map((m, i) => (
                    <div key={i} style={{ display: "flex", gap: 12, padding: "13px 15px", background: "#f8f5ef", borderRadius: 14, alignItems: "flex-start" }}>
                      <span style={{ fontSize: 22, flexShrink: 0 }}>{m.icon}</span>
                      <div>
                        <div style={{ fontWeight: 700, fontSize: 13, color: "#1B4332", marginBottom: 2 }}>{m.method}</div>
                        <div style={{ fontSize: 12, color: "#6b7280", lineHeight: 1.5 }}>{m.detail}</div>
                      </div>
                    </div>
                  ))}
                </div>
                <div style={{ marginTop: 12, padding: "10px 14px", background: "#fef9c3", borderRadius: 10, border: "1px solid #fde047" }}>
                  <p style={{ fontSize: 12, color: "#92400e", margin: 0, fontStyle: "italic" }}>💬 เป็นภูมิปัญญาพื้นบ้าน ไม่ควรใช้แทนคำแนะนำทางการแพทย์</p>
                </div>
              </div>
            </div>

            {/* ชนิดย่อย */}
            {herb.varieties && (
              <div style={{ background: "#fff", borderRadius: 24, padding: 28, boxShadow: "0 2px 20px rgba(27,67,50,0.07)", border: "1px solid #e8f5e9" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 18 }}>
                  <span style={{ fontSize: 26 }}>🌱</span>
                  <h2 style={{ fontFamily: "'Noto Serif Thai',serif", fontSize: 20, fontWeight: 700, color: "#1B4332", margin: 0 }}>ชนิดของ{herb.name}</h2>
                </div>
                <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                  {herb.varieties.map((v, i) => (
                    <div key={i} style={{ padding: "16px 18px", background: v.bg, borderRadius: 16, border: `1.5px solid ${v.color}30` }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
                        <span style={{ fontSize: 22 }}>{v.icon}</span>
                        <div>
                          <div style={{ fontWeight: 700, fontSize: 15, color: v.color }}>{v.name}</div>
                          <div style={{ fontSize: 12, color: "#6b7280", fontStyle: "italic" }}>{v.latin}</div>
                        </div>
                      </div>
                      <p style={{ fontSize: 13, color: "#374151", lineHeight: 1.6, margin: 0 }}>{v.detail}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* ใครไม่ควรใช้ */}
            <div style={{ background: "#fff", borderRadius: 24, padding: 28, boxShadow: "0 2px 20px rgba(27,67,50,0.07)", border: "1px solid #e8f5e9" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
                <span style={{ fontSize: 26 }}>🚫</span>
                <h2 style={{ fontFamily: "'Noto Serif Thai',serif", fontSize: 20, fontWeight: 700, color: "#b91c1c", margin: 0 }}>ใครไม่ควรใช้</h2>
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {(herb.warnings||[]).map((w, i) => (
                  <div key={i} style={{ display: "flex", gap: 14, padding: "13px 16px", background: w.bg, borderRadius: 14, border: `1.5px solid ${w.color}25`, alignItems: "flex-start" }}>
                    <span style={{ fontSize: 24, flexShrink: 0 }}>{w.icon}</span>
                    <span style={{ fontSize: 14, color: w.color, fontWeight: 600, lineHeight: 1.5 }}>{w.text}</span>
                  </div>
                ))}
              </div>
            </div>

            {/* ข้อควรระวัง */}
            <div style={{ background: "#fef9c3", borderRadius: 24, padding: 24, border: "2px solid #fde047" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 14 }}>
                <span style={{ fontSize: 24 }}>⚠️</span>
                <h2 style={{ fontFamily: "'Noto Serif Thai',serif", fontSize: 18, fontWeight: 700, color: "#92400e", margin: 0 }}>ข้อควรระวัง</h2>
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {(herb.cautions||[]).map((ct, i) => (
                  <div key={i} style={{ display: "flex", gap: 10, alignItems: "center", padding: "11px 14px", background: "rgba(255,255,255,0.6)", borderRadius: 12 }}>
                    <span style={{ fontSize: 16, flexShrink: 0 }}>👉</span>
                    <span style={{ fontSize: 14, fontWeight: 600, color: "#92400e" }}>{ct}</span>
                  </div>
                ))}
              </div>
            </div>

          </div>
        </div>

        {/* Everyday Use — แสดงเฉพาะถ้ามีข้อมูล */}
        {herb.everydayUse && (
          <div style={{ marginTop: 24, background: "#fff", borderRadius: 24, padding: 28, boxShadow: "0 2px 20px rgba(27,67,50,0.07)", border: "1px solid #e8f5e9" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 18 }}>
              <span style={{ fontSize: 26 }}>🍛</span>
              <h2 style={{ fontFamily: "'Noto Serif Thai', serif", fontSize: 20, fontWeight: 700, color: "#1B4332", margin: 0 }}>การนำไปใช้ในชีวิตประจำวัน</h2>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 14 }}>
              {herb.everydayUse.map((u, i) => (
                <div key={i} style={{ padding: "18px 16px", background: "#f8f5ef", borderRadius: 18, border: "1px solid #e8f5e9", textAlign: "center" }}>
                  <div style={{ fontSize: 32, marginBottom: 10 }}>{u.icon}</div>
                  <div style={{ fontWeight: 700, fontSize: 14, color: "#1B4332", marginBottom: 6 }}>{u.category}</div>
                  <div style={{ fontSize: 12, color: "#6b7280", lineHeight: 1.6 }}>{u.detail}</div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* ── References + Disclaimer ── */}
        <div style={{ marginTop: 24, display: "flex", flexDirection: "column", gap: 16 }}>

          {/* References */}
          <div style={{ background: "#fff", borderRadius: 24, padding: 28,
            boxShadow: "0 2px 20px rgba(27,67,50,0.07)", border: "1px solid #e8f5e9" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 18 }}>
              <span style={{ fontSize: 24 }}>📚</span>
              <h2 style={{ fontFamily: "'Noto Serif Thai',serif", fontSize: 18, fontWeight: 700, color: "#1B4332", margin: 0 }}>ข้อมูลอ้างอิง</h2>
            </div>
            <p style={{ fontSize: 13, color: "#6b7280", marginBottom: 16, lineHeight: 1.6 }}>
              ข้อมูลในหน้านี้เรียบเรียงจากแหล่งข้อมูลที่เชื่อถือได้ ได้แก่
            </p>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              {[
                { name: "กรมการแพทย์แผนไทยและการแพทย์ทางเลือก", url: "https://www.dtam.moph.go.th", icon: "🏛️" },
                { name: "โรงพยาบาลเจ้าพระยาอภัยภูเบศร", url: "https://www.abhaiherb.com", icon: "🏥" },
                { name: "สำนักงานคณะกรรมการอาหารและยา (อย.)", url: "https://www.fda.moph.go.th", icon: "🔬" },
                { name: "WHO Traditional Medicine", url: "https://www.who.int/health-topics/traditional-complementary-and-integrative-medicine", icon: "🌐" },
                { name: "PubMed — National Library of Medicine", url: "https://pubmed.ncbi.nlm.nih.gov", icon: "📖" },
                { name: "กรมวิทยาศาสตร์การแพทย์", url: "https://www.dmsc.moph.go.th", icon: "🧪" },
              ].map((ref, i) => (
                <a key={i} href={ref.url} target="_blank" rel="noopener noreferrer"
                  style={{ display: "flex", alignItems: "center", gap: 10, padding: "12px 14px",
                    background: "#f8f5ef", borderRadius: 12, border: "1px solid #e8f5e9",
                    textDecoration: "none", transition: "all 0.15s",
                    color: "#1B4332" }}>
                  <span style={{ fontSize: 18, flexShrink: 0 }}>{ref.icon}</span>
                  <span style={{ fontSize: 12, fontWeight: 600, lineHeight: 1.4, flex: 1 }}>{ref.name}</span>
                  <span style={{ fontSize: 10, color: "#9ca3af", flexShrink: 0 }}>↗</span>
                </a>
              ))}
            </div>
          </div>

          {/* Disclaimer */}
          <div style={{ background: "#fef9c3", borderRadius: 20, padding: "18px 22px",
            border: "1.5px solid #fde047", display: "flex", gap: 14, alignItems: "flex-start" }}>
            <span style={{ fontSize: 22, flexShrink: 0 }}>⚠️</span>
            <div>
              <div style={{ fontWeight: 700, fontSize: 14, color: "#92400e", marginBottom: 6 }}>ข้อควรทราบ</div>
              <p style={{ fontSize: 13, color: "#78350f", lineHeight: 1.7, margin: 0 }}>
                ข้อมูลทั้งหมดจัดทำขึ้นเพื่อการให้ความรู้เกี่ยวกับสมุนไพรไทยเท่านั้น ไม่สามารถใช้แทนการวินิจฉัย การรักษา หรือคำแนะนำจากแพทย์ เภสัชกร หรือบุคลากรทางการแพทย์ หากมีอาการรุนแรง ใช้ยาประจำ ตั้งครรภ์ หรือมีโรคประจำตัว <strong>ควรปรึกษาแพทย์ก่อนใช้สมุนไพร</strong>
              </p>
            </div>
          </div>
        </div>

        {/* AI Chat — full width horizontal layout */}
        <div style={{ marginTop: 24, background: "#fff", borderRadius: 24, padding: 24, boxShadow: "0 2px 20px rgba(27,67,50,0.07)", border: "1px solid #e8f5e9" }}>
          {/* Header */}
          <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 16 }}>
            <div style={{ width: 44, height: 44, borderRadius: 14, background: "linear-gradient(135deg, #1B4332, #166534)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 22, flexShrink: 0 }}>🐱</div>
            <div style={{ flex: 1 }}>
              <div style={{ fontWeight: 700, fontSize: 16, color: "#1B4332" }}>ถามหมอแมวได้เลย</div>
              <div style={{ fontSize: 12, color: "#6b7280" }}>AI ตอบแบบเข้าใจง่าย ไม่มีศัพท์ยาก — ⚠️ ข้อมูลเพื่อการศึกษา ควรปรึกษาแพทย์ก่อนใช้เสมอ</div>
            </div>
          </div>

          {/* Horizontal body: suggested left | chat right */}
          <div style={{ display: "grid", gridTemplateColumns: "200px 1fr", gap: 20, alignItems: "stretch" }}>

            {/* Left: suggested questions */}
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: "#9ca3af", letterSpacing: "0.07em", textTransform: "uppercase", marginBottom: 4 }}>คำถามยอดนิยม</div>
              {sugQ.map((q, i) => (
                <button key={i} onClick={() => send(q)} style={{
                  padding: "9px 14px", borderRadius: 12,
                  border: "1.5px solid #bbf7d0", background: "#f0fdf4",
                  color: "#15803d", fontSize: 13, fontWeight: 600,
                  cursor: "pointer", fontFamily: "inherit", textAlign: "left",
                  transition: "all 0.15s"
                }}>{q}</button>
              ))}
            </div>

            {/* Right: chat window + input */}
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              <div style={{ flex: 1, minHeight: 160, maxHeight: 200, overflowY: "auto",
                display: "flex", flexDirection: "column", gap: 10,
                padding: "12px 14px", background: "#f8f5ef", borderRadius: 16 }}>
                {messages.map((m, i) => {
                  const isU = m.role === "user";
                  return (
                    <div key={i} style={{ display: "flex", justifyContent: isU ? "flex-end" : "flex-start", gap: 7, alignItems: "flex-end" }}>
                      {!isU && <span style={{ fontSize: 18, flexShrink: 0 }}>😺</span>}
                      <div style={{ maxWidth: "78%", padding: "9px 14px",
                        borderRadius: isU ? "16px 16px 4px 16px" : "16px 16px 16px 4px",
                        background: isU ? "#1B4332" : "#fff",
                        color: isU ? "#fff" : "#1f2937",
                        fontSize: 13, lineHeight: 1.6,
                        border: isU ? "none" : "1px solid #e8f5e9",
                        boxShadow: "0 1px 4px rgba(0,0,0,0.06)"
                      }}>{m.text}</div>
                    </div>
                  );
                })}
                {loading && (
                  <div style={{ display: "flex", gap: 7, alignItems: "flex-end" }}>
                    <span style={{ fontSize: 18 }}>😺</span>
                    <div style={{ padding: "9px 14px", borderRadius: "16px 16px 16px 4px", background: "#fff", border: "1px solid #e8f5e9", boxShadow: "0 1px 4px rgba(0,0,0,0.06)" }}>
                      <div style={{ display: "flex", gap: 4 }}>
                        {[0,1,2].map(i => <div key={i} style={{ width: 6, height: 6, borderRadius: "50%", background: "#16a34a", animation: "bounce 1.2s infinite", animationDelay: `${i*0.2}s` }} />)}
                      </div>
                    </div>
                  </div>
                )}
              </div>
              <div style={{ display: "flex", gap: 8 }}>
                <input value={input} onChange={e => setInput(e.target.value)}
                  onKeyDown={e => e.key === "Enter" && send()}
                  placeholder="พิมพ์คำถามเกี่ยวกับสมุนไพร..."
                  style={{ flex: 1, padding: "11px 16px", borderRadius: 12, border: "1.5px solid #e5e7eb", fontSize: 13, outline: "none", fontFamily: "inherit", background: "#f8f5ef" }} />
                <button onClick={() => send()} disabled={loading}
                  style={{ padding: "11px 22px", borderRadius: 12, background: "#1B4332", color: "#fff", border: "none", fontWeight: 700, fontSize: 13, cursor: "pointer", fontFamily: "inherit", opacity: loading ? 0.5 : 1, whiteSpace: "nowrap" }}>ส่ง →</button>
              </div>
            </div>
          </div>
        </div>

      </div>

      {/* Footer */}
      <footer style={{ background: "#1B4332", color: "#fff", padding: "28px 24px", textAlign: "center" }}>
        <div style={{ maxWidth: 1000, margin: "0 auto" }}>
          <div style={{ fontSize: 28, marginBottom: 6 }}>🐾</div>
          <div style={{ fontFamily: "'Noto Serif Thai', serif", fontWeight: 700, fontSize: 18, marginBottom: 6 }}>หมอยาเหมียวๆ</div>
          <p style={{ fontSize: 12, opacity: 0.55, margin: 0 }}>ข้อมูลทั้งหมดเพื่อการศึกษา ควรปรึกษาแพทย์หรือเภสัชกรก่อนใช้ยาสมุนไพรทุกชนิด</p>
        </div>
      </footer>
    </div>
  );
}

// ─── App Router ──────────────────────────────────────────────────────────────
export default function App() {
  const [currentHerb, setCurrentHerb] = useState(null);
  const [showAbout, setShowAbout] = useState(false);

  return (
    <div style={{ fontFamily: "'Noto Sans Thai', 'Sarabun', sans-serif", color: "#1f2937" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Noto+Serif+Thai:wght@700&family=Noto+Sans+Thai:wght@400;500;600;700&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        @keyframes bounce { 0%,80%,100%{transform:translateY(0)} 40%{transform:translateY(-5px)} }
        button { font-family: inherit; }
        input { font-family: inherit; }
        ::-webkit-scrollbar { width: 5px; }
        ::-webkit-scrollbar-thumb { background: #a7f3d0; border-radius: 3px; }
      `}</style>
      <NavBar onHome={() => setCurrentHerb(null)} onAbout={() => setShowAbout(true)} />
      {currentHerb
        ? <DetailPage herb={currentHerb} onBack={() => setCurrentHerb(null)} />
        : <HomePage onSelectHerb={setCurrentHerb} />
      }

      {/* ── About Modal ── */}
      {showAbout && (
        <div onClick={() => setShowAbout(false)} style={{
          position: "fixed", inset: 0, zIndex: 999,
          background: "rgba(0,0,0,0.65)", backdropFilter: "blur(6px)",
          display: "flex", alignItems: "center", justifyContent: "center", padding: 20
        }}>
          <div onClick={e => e.stopPropagation()} style={{
            background: "#fff", borderRadius: 28, maxWidth: 560, width: "100%",
            maxHeight: "90vh", overflowY: "auto",
            boxShadow: "0 24px 80px rgba(0,0,0,0.3)"
          }}>
            <div style={{ background: "linear-gradient(135deg,#1B4332,#166534)",
              borderRadius: "28px 28px 0 0", padding: "22px 28px",
              display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <div style={{ fontSize: 11, color: "#86efac", fontWeight: 700, letterSpacing: "0.1em", marginBottom: 4, textTransform: "uppercase" }}>เกี่ยวกับเรา</div>
                <h2 style={{ fontFamily: "'Noto Serif Thai',serif", fontSize: 22, fontWeight: 700, color: "#fff", margin: 0 }}>ประวัติเว็บไซต์</h2>
              </div>
              <button onClick={() => setShowAbout(false)} style={{
                width: 36, height: 36, borderRadius: "50%",
                background: "rgba(255,255,255,0.2)", border: "none",
                color: "#fff", fontSize: 18, cursor: "pointer",
                display: "flex", alignItems: "center", justifyContent: "center"
              }}>✕</button>
            </div>
            <div style={{ padding: "24px 28px 0" }}>
              <img src={ABOUT_PHOTO} alt="ผู้จัดทำ" style={{
                width: "100%", borderRadius: 18, objectFit: "cover", maxHeight: 300,
                boxShadow: "0 4px 20px rgba(27,67,50,0.15)", display: "block"
              }} />
            </div>
            <div style={{ padding: "22px 28px 30px", display: "flex", flexDirection: "column", gap: 14 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 12,
                background: "#f0fdf4", border: "1px solid #bbf7d0",
                borderRadius: 14, padding: "12px 16px" }}>
                <span style={{ fontSize: 22, flexShrink: 0 }}>👩‍🎓</span>
                <div>
                  <div style={{ fontWeight: 700, fontSize: 15, color: "#1B4332" }}>นางสาวณัฏฐกานต์ โพธิ์ศรี</div>
                  <div style={{ fontSize: 12, color: "#6b7280" }}>นักเรียนชั้นมัธยมศึกษาปีที่ 6 · ผู้จัดทำเว็บไซต์</div>
                </div>
              </div>
              <div style={{ padding: "14px 16px", background: "#f8f5ef", borderRadius: 14 }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: "#1B4332", marginBottom: 6 }}>🌿 ที่มาและแนวคิด</div>
                <p style={{ fontSize: 13, color: "#374151", lineHeight: 1.8, margin: 0 }}>
                  เว็บไซต์ <strong>หมอยาเหมียวๆ</strong> จัดทำขึ้นจากความสนใจด้านสมุนไพรไทยและภูมิปัญญาท้องถิ่น โดยมีความตั้งใจที่จะรวบรวมองค์ความรู้เกี่ยวกับสมุนไพรที่พบได้รอบตัวไว้ในแหล่งข้อมูลเดียว เพื่อให้ทุกคนสามารถศึกษา ค้นคว้า และนำไปใช้ประโยชน์ได้อย่างสะดวก
                </p>
              </div>
              <div style={{ padding: "14px 16px", background: "#eff6ff", borderRadius: 14, border: "1px solid #bfdbfe" }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: "#1565C0", marginBottom: 6 }}>💡 วัตถุประสงค์</div>
                <p style={{ fontSize: 13, color: "#374151", lineHeight: 1.8, margin: 0 }}>
                  สมุนไพรไทยเป็นทรัพยากรที่มีคุณค่า แต่ข้อมูลยังคงกระจัดกระจายและเข้าใจได้ยากสำหรับคนทั่วไป จึงต้องการนำเสนอข้อมูลในรูปแบบที่ <strong>อ่านง่าย น่าสนใจ และเข้าถึงได้ทุกเพศทุกวัย</strong>
                </p>
              </div>
              <div style={{ padding: "14px 16px", background: "#f0fdf4", borderRadius: 14, border: "1px solid #bbf7d0" }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: "#15803d", marginBottom: 6 }}>🎯 เป้าหมาย</div>
                <p style={{ fontSize: 13, color: "#374151", lineHeight: 1.8, margin: 0 }}>
                  หมอยาเหมียวๆ ไม่ใช่เพียงเว็บไซต์รวบรวมข้อมูลสมุนไพรเท่านั้น แต่เป็น <strong>พื้นที่แห่งการเรียนรู้</strong> ที่มุ่งหวังให้คนรุ่นใหม่ได้เห็นคุณค่าของสมุนไพรไทย พร้อมสืบสานภูมิปัญญาดั้งเดิมให้คงอยู่และต่อยอดในชีวิตประจำวัน
                </p>
              </div>
              <div style={{ padding: "16px 18px", background: "#f0fdf4", borderRadius: 14, border: "1px solid #bbf7d0" }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: "#15803d", marginBottom: 10 }}>🏛️ มาตรฐานข้อมูล</div>
                <p style={{ fontSize: 13, color: "#374151", lineHeight: 1.7, margin: "0 0 12px" }}>
                  เว็บไซต์หมอยาเหมียวๆ รวบรวมข้อมูลจากหน่วยงานภาครัฐ หนังสือวิชาการ และงานวิจัยที่เกี่ยวข้อง เพื่อให้ข้อมูลมีความถูกต้อง น่าเชื่อถือ และเข้าใจง่าย
                </p>
                <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                  {["กรมการแพทย์แผนไทยฯ","อย.","WHO","PubMed","รพ.อภัยภูเบศร","กรมวิทยาศาสตร์การแพทย์"].map((src, i) => (
                    <span key={i} style={{ fontSize: 11, fontWeight: 600, color: "#15803d",
                      background: "#dcfce7", padding: "4px 10px", borderRadius: 999,
                      border: "1px solid #bbf7d0" }}>{src}</span>
                  ))}
                </div>
              </div>
              <div style={{ padding: "12px 16px", background: "#1B4332", borderRadius: 12, textAlign: "center" }}>
                <p style={{ fontSize: 13, color: "#86efac", margin: 0, fontStyle: "italic" }}>
                  🐾 "สมุนไพรไทย ภูมิปัญญาไทย สืบสานไว้ให้คนรุ่นหลัง"
                </p>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
